use crate::aap::caps::kb_read;

/// Upper bound on the question carried into the output (ensures clause).
const MAX_QUESTION_BYTES: usize = 512;

/// Placeholder used when the knowledge base returns nothing, so that
/// `present(knowledge)` holds of the output.
const NO_MATCH: &str = "(no knowledge-base entries matched this question)";

/// Truncate to at most MAX_QUESTION_BYTES bytes on a char boundary.
/// The `requires` clause already guarantees the input fits, so this is a
/// no-op on valid inputs; it keeps the `ensures` clause true unconditionally.
fn bound_question(q: &str) -> String {
    let mut end = 0;
    for (i, c) in q.char_indices() {
        let next = i + c.len_utf8();
        if next > MAX_QUESTION_BYTES {
            break;
        }
        end = next;
    }
    q[..end].to_string()
}

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(&query.query.question);

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_MATCH.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
